    if(oi.items.length){ wrapSegs(f,[{text:T.oiLabel+' ',b:true,i:false},{text:oi.text,b:false,i:false}],S.oiSize,W,0).forEach(l=>{ ey+=olh; ext.push({t:'text',x:0,y:ey-olh*0.22,segs:l,size:S.oiSize,grp:'Other_Ingredients'}); }); }
