  return `<svg xmlns="http://www.w3.org/2000/svg" ${size} viewBox="0 0 ${trim(vbW)} ${trim(Hall)}">${forExport?`<title>Supplement Facts - ${esc(p.name)}</title>`:''}${body}${overlay}</svg>`;
