  const catalogId=add(null), pagesId=add(null), pageId=add(null);
  const contentId=add(`<< /Length ${c.length} >>\nstream\n${c}endstream`);
  const fontRefs=[];
  for(const [ps,info] of fontsUsed){
    const widths=[]; for(let code=32;code<=255;code++){ const u = (code>=0x80&&code<=0x9F)? (WIN_REV[code]||32) : code; widths.push(Math.round(measure(info.font,{text:String.fromCodePoint(u),b:info.b,i:info.i},1000))); }
    const flags = 32 + (info.i?64:0);
    const fd=add(`<< /Type /FontDescriptor /FontName /${ps} /Flags ${flags} /FontBBox [-200 -250 1200 950] /ItalicAngle ${info.i?-11:0} /Ascent 750 /Descent -250 /CapHeight 674 /StemV ${info.b?140:88} >>`);
    const fid=add(`<< /Type /Font /Subtype /Type1 /BaseFont /${ps} /Encoding /WinAnsiEncoding /FirstChar 32 /LastChar 255 /Widths [${widths.join(' ')}] /FontDescriptor ${fd} 0 R >>`);
    fontRefs.push(`/${info.res} ${fid} 0 R`);
  }
  objs[catalogId-1]=`<< /Type /Catalog /Pages ${pagesId} 0 R >>`;
  objs[pagesId-1]=`<< /Type /Pages /Kids [${pageId} 0 R] /Count 1 >>`;
  objs[pageId-1]=`<< /Type /Page /Parent ${pagesId} 0 R /MediaBox [0 0 ${trim(W)} ${trim(H)}] /TrimBox [0 0 ${trim(W)} ${trim(H)}] /Resources << /Font << ${fontRefs.join(' ')} >> >> /Contents ${contentId} 0 R >>`;
  const infoId=add(`<< /Title ${pdfStr('Supplement Facts - '+p.name)} /Producer (NutraPack Panel Builder) >>`);
  let out='%PDF-1.4\n%\xE2\xE3\xCF\xD3\n'; const offs=[];
  objs.forEach((o,i)=>{ offs.push(out.length); out+=`${i+1} 0 obj\n${o}\nendobj\n`; });
  const xref=out.length;
